entries[70924] = { ["name"] = "Ewiges Auge der Elune", ["text"] = "Geschmolzene Front\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt im Verlauf von 5 Sek. 4615 Gesundheit und ( 960 * 5) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 5 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 15 Intelligenz und 14 Ausdauer. (1 Min Abklingzeit)\n\"Dieses saftige Kernobst platzt fast vor süßem Geschmack. Nur an der Geschmolzenen Front einsetzbar.\"" }
